function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	'ma_dvcs, ma_kh, ma_hd'.split(',').forEach(function(e) { changeLookupReadonly(f, $func.trim(e)) })
	onChange$&controller;$Type(f);			
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result, v = f.getItemValue('mau_bc')
	switch (context) {
		case 'Checking':
			var g = f.grid, period = f.getItem('thang').value, year = f.getItem('nam').value, x = f.getItem('form').selectedIndex, y = f.getItem('form').options, formName = y[x].text;
			g._alterTitle = [null, [['%f', formName, true], ['%p', period, true], ['%y', year, true], ['%v', f.getItemValue('ma_vv'), true ]]];			
			g._queryFilterString = getQueryFilterString(f, 'form, mau_bc, ma_dvcs, thang, nam, ma_vv');			
			break;
		default:
			break;
	}
}
/* </flatten> */
function onChange$&controller;$Item(o) {
	var f = o.parentForm, name = o.field.Name;
	switch (name) {
		case 'kieu_dt':
			onChange$&controller;$Type(f, true);
			break;
		default:
			break;
	}
}
function onChange$&controller;$Type(f, force) {window.setTimeout(String.format('onFocus$&controller;$Type(\'{0}\', {1});', f._id, force ? 1 : 0), 2);}
function onFocus$&controller;$Type(id, force) {
	var f = $find(id), v = (f.getItem('kieu_dt').value == '3'), t1 = f.getItem('so_cs'), t2 = f.getItem('ma_vv');
	setItem$&controller;$Disable(f, 'so_cs', !v);
	setItem$&controller;$Live(t1, t2, v)
}
function setItem$&controller;$Live(t1, t2, type) {
	if (type) {if (t2.live) {t1.disabled = false; t1.focus();}}
		else {if (t1.live) {t2.disabled = false; t2.focus();}}
}
function setItem$&controller;$Disable(f, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var o = f.getItem($func.trim(a[i]));
		if (o.a) $common.setVisible(o.a, !v);
		o.disabled = v;
	}
}
function init$&controller;$Form(f) {
	var o = f.getItem('form'), value = f._itemValue.split(String.fromCharCode(255)), text = f._itemText.split(String.fromCharCode(255)), index;
	for (var i = 0; i < value.length; i++) {
		o.options[i] = new Option(text[i], value[i]);
		if (!index && f._defaultForm == value[i]) index = i;
	}
	if (!index) index = 0;
	o.options[index].selected = true;
}
/* <flatten type="Javascript"> */
function onChange$Period$PeriodBudgetReport(obj) {
	var f = obj.parentForm;
	if (f.getItemValue(obj.field.Name) < 1) f.setItemValue(obj.field.Name, 1)
	else if (f.getItemValue(obj.field.Name) > 12) f.setItemValue(obj.field.Name, 12);
}
